mapper.select:
select (CASE WHEN secAcctName = '' THEN secAcctId END) as chIld, (CASE WHEN chIldName = '' THEN secAcctId END) aa.pspAmount + aa.flowAmount as bconShareAmt,aa.* from ( select psp.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, PSP.SEC_ACCT_ID secAcctId, si.sec_acct_name secAcctName, (SELECT IFNULL(A.FINPROD_ABBR, A.FINPROD_NAME) FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_ADD B ON A.FINPROD_ID = B.FINPROD_ID where A.FINPROD_ID = psp.sec_acct_id) chIldName, IFNULL(psp.AMOUNT,0) pspAmount,
IFNULL(0,0) flowAmount
(select IFNULL(sum(amount),0) from PTL_SEC_POSITION_flow where PORTFOLIO_ID = psp.portfolio_id and sec_acct_id = psp.sec_acct_id and finprod_id = psp.finprod_id and hoding_type='01') flowAmount
from PTL_SEC_POSITION psp inner join FIN_PRODUCT fp on fp.FINPROD_ID = psp.FINPROD_ID inner join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = psp.PORTFOLIO_ID left join STL_SEC_ACCT_INFO si on si.sec_acct_id = PSP.SEC_ACCT_ID where IFNULL(pp.PARENT_PORTFOLIO_ID,'null') = 'null' and psp.CDATE = #{conversionTime,jdbcType=DATE}
and psp.AMOUNT >0 and fp.FINPROD_MARKET_ID = #{finprodMarketId,jdbcType=VARCHAR}
and psp.HODING_TYPE = #{POSITION_TYPE03}
and IFNULL(pp.PARENT_PORTFOLIO_ID,'null') = 'null' order by AMOUNT) aa

choose.when:
select psp.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, psp.AMOUNT registShare,
pp.INVEST_YESORNO investYesorno,
psp.CDATE registDate from PTL_SEC_POSITION psp inner join FIN_PRODUCT fp on fp.FINPROD_ID = psp.FINPROD_ID inner join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = psp.PORTFOLIO_ID where IFNULL(pp.PARENT_PORTFOLIO_ID,'null') = 'null' and psp.CDATE = #{registDate,jdbcType=DATE}
AND PSP.SEC_ACCT_ID = #{chlId}
AND PSP.SEC_ACCT_ID = '999999'
and psp.AMOUNT >0 and fp.FINPROD_MARKET_ID = #{finprodMarketId,jdbcType=VARCHAR}
and psp.HODING_TYPE = #{POSITION_TYPE03}
and IFNULL(pp.PARENT_PORTFOLIO_ID,'null') = 'null' order by AMOUNT

mapper.select:
select pt.portfolio_id, ppf.portfolio_name portfolioName, tpd.chl_id chIld, (SELECT IFNULL(A.FINPROD_ABBR, A.FINPROD_NAME) FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_ADD B ON A.FINPROD_ID = B.FINPROD_ID where A.FINPROD_ID = tpd.chl_id) chIldName, tpd.SEC_MANAGE_ACCT_ID secAcctId, (select sec_acct_name from STL_SEC_ACCT_INFO si where si.sec_acct_id = tpd.SEC_MANAGE_ACCT_ID) secAcctName, ptpd.acon_share_amt,ptpd.bcon_share_amt from ptl_trade pt left join TRD_PRODUCT_DEAL tpd on pt.busi_no = tpd.trade_id left join PA_TRD_PRODUCT_DEAL ptpd on tpd.trade_id = ptpd.trade_id left join ptl_portfolio ppf on ppf.portfolio_id = pt.portfolio_id
and tpd.totle_trade_id = #{totleTradeId}
and tpd.is_cancel='N' and IFNULL(ppf.PARENT_PORTFOLIO_ID,'null') = 'null'

mapper.sql:

and tpd.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F06}


    and fprod_type.TYPE_6 = #{finprodType}



    and fp.FINPROD_MARKET_ID = #{finprodMarketId}



    and IFNULL(tpda.PAY_TYPE,wtpda.PAY_TYPE) = #{bonusMode}


    and wtdta.conversion_type = #{conversionType}


    and tpd.TRADE_DATE >= STR_TO_DATE(#{conversionTimeStart},'%Y-%m-%d')
    and tpd.TRADE_DATE <= STR_TO_DATE(#{conversionTimeEnd},'%Y-%m-%d')

mapper.select:
select * from (select temp_data.*,
tmpTable.hasFlow
from(

    /*流程中*/
    SELECT
    #{PAGE_DATE_STATUS03} statusValid,

    tpd.WORKFLOW_ID workflowId
    from
    WFL_TRD_FIN_PRODUCT_DEAL_TOTAL tpd

    where
    tpd.PS=#{ps}


    and tpd.TRADE_STATUS = #{TRADE_STATUS01}
    and tpd.IS_CANCEL = #{YESNO_N}





        UNION ALL

    SELECT
    #{PAGE_DATE_STATUS05} statusValid,

    null workflowId
    from
    TRD_FIN_PRODUCT_DEAL_TOTAL  tpd

    where
    tpd.PS=#{ps}

    and tpd.TRADE_STATUS = #{TRADE_STATUS01}
    and tpd.IS_CANCEL = #{YESNO_N}


/*撤销数据*/


        UNION ALL

    SELECT
    #{PAGE_DATE_STATUS06} statusValid,

    null workflowId
    FROM
    TRD_FIN_PRODUCT_DEAL_TOTAL  tpd

    where
    tpd.PS=#{ps}

    and tpd.TRADE_STATUS = #{TRADE_STATUS03}
    and tpd.IS_CANCEL = #{YESNO_N}


) temp_data
left join (
select distinct B_TRADE_ID,hasFlow from (
SELECT B_TRADE_ID,'01' hasFlow FROM TRD_FIN_PRODUCT_DEAL_TOTAL total where total.B_TRADE_ID is not null
and total.TRADE_STATUS = #{TRADE_STATUS01}
and total.FINPROD_TYPE2 = #{finprodTypeTg}
and total.IS_CANCEL = #{YESNO_N}
UNION all
SELECT B_TRADE_ID,'01' hasFlow FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL total where total.B_TRADE_ID is not null
and total.TRADE_STATUS = #{TRADE_STATUS01}
and total.FINPROD_TYPE2 = #{finprodTypeTg}
and total.IS_CANCEL = #{YESNO_N})
)tmpTable on tmpTable.B_TRADE_ID = temp_data.TOTLE_TRADE_ID
order by temp_data.conversionTime desc)
